<script setup>
import { ref, reactive, onMounted } from 'vue';
import { usePatientStore } from '../../../stores/patients';
import { useClinicContextStore } from '../../../stores/clinicContext';
import { patientService } from '../../../services/patients';
import FormErrors from '../../../components/ui/FormErrors.vue';
const store = usePatientStore(), context = useClinicContextStore();
const result = ref(null), error = ref(null), busy = ref(false), uploading = ref(false), file = ref(null), fileInput = ref(null), removing = ref(null);
const form = reactive({ title: '', document_type: 'medical_report', description: '' });
async function load(page = 1) { busy.value = true; error.value = null; try { result.value = (await patientService.entries(store.patient.id, 'documents', page)).data.data; } catch (e) { error.value = e; } finally { busy.value = false; } }
async function upload() { const data = new FormData(); Object.entries(form).forEach(([key,value]) => data.append(key,value)); if (file.value) data.append('file',file.value); busy.value = true; error.value = null; try { await patientService.upload(store.patient.id,data); uploading.value = false; form.title = ''; form.description = ''; file.value = null; await load(); } catch (e) { error.value = e; } finally { busy.value = false; } }
async function download(document) { error.value = null; try { await patientService.download(store.patient.id,document); } catch (e) { error.value = e; } }
async function archive() { busy.value = true; try { await patientService.archiveDocument(store.patient.id, removing.value.id); removing.value = null; await load(); } catch (e) { error.value = e; } finally { busy.value = false; } }
onMounted(() => load());
</script>
<template><section class="clinic-panel"><div class="clinic-card-heading"><div><h2>Patient documents</h2><p class="text-xs text-slate-500 mt-2">Private files · PDF, JPG or PNG · Up to 10 MB each</p></div><button v-if="context.can('patients.documents.upload') && store.patient.status !== 'archived'" class="btn" @click="uploading = !uploading">Upload Document</button></div><FormErrors :error="error" /><button v-if="error && !uploading" class="btn-secondary" @click="load()">Try again</button><form v-if="uploading" class="patient-history-form mb-5" @submit.prevent="upload"><label class="field">Document title<input v-model="form.title" required maxlength="150"></label><label class="field">Document type<select v-model="form.document_type"><option v-for="type in ['medical_report','referral','laboratory_report','identification','insurance','other']" :key="type" :value="type">{{ type.replaceAll('_',' ') }}</option></select></label><label class="field">Description<textarea v-model="form.description" maxlength="2000"></textarea></label><label class="field">File<input ref="fileInput" type="file" accept=".pdf,.jpg,.jpeg,.png" required @change="file = $event.target.files[0]"></label><div class="flex gap-3"><button class="btn" :disabled="busy">Save Document</button><button type="button" class="btn-secondary" @click="uploading = false">Cancel</button></div></form><p v-if="busy" class="empty-state">Loading documents...</p><template v-else-if="result"><div v-for="document in result.data" :key="document.id" class="patient-document-row"><div><strong>{{ document.title }}</strong><p class="mt-2 text-xs text-slate-500 capitalize">{{ document.document_type.replaceAll('_',' ') }} · {{ (document.size / 1024).toFixed(1) }} KB · {{ new Date(document.created_at).toLocaleDateString() }} · {{ document.recorder?.name || 'Clinic staff' }}</p><p class="mt-2 text-sm text-slate-500">{{ document.description }}</p></div><div class="flex gap-3"><button class="btn-secondary" @click="download(document)">Download</button><button v-if="context.can('patients.documents.delete')" class="btn-secondary" @click="removing = document">Archive</button></div></div><p v-if="!result.data.length" class="empty-state">No documents uploaded.</p><div v-if="result.last_page > 1" class="patient-pagination"><button :disabled="result.current_page === 1" @click="load(result.current_page - 1)">Previous</button><span>{{ result.current_page }} / {{ result.last_page }}</span><button :disabled="result.current_page === result.last_page" @click="load(result.current_page + 1)">Next</button></div></template></section><Teleport to="body"><div v-if="removing" class="modal-backdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="document-confirm"><h2 id="document-confirm" class="text-xl font-bold">Archive {{ removing.title }}?</h2><p class="my-4 text-slate-500">The document will be removed from this list and retained securely.</p><div class="flex justify-end gap-3"><button class="btn-secondary" :disabled="busy" @click="removing = null">Cancel</button><button class="btn" :disabled="busy" @click="archive">Archive Document</button></div></section></div></Teleport></template>
